    // Step 4: Check and adjust car price if necessary
    if (carPrice < 2 * clothesBookCombinedPrice)
    {
        adjustedCarPrice = 2 * clothesBookCombinedPrice;
        carPrice = adjustedCarPrice;
    }

    // Step 5: Calculate total cost of purchase
    decimal totalCost = carPrice + clothesPrice + bookPrice;

    // Step 6: Return total cost
